        if order.usuario_id == previous_user_id:
            # Preserva todos os itens e o pedido antigo para auditoria, mas impede edição simultânea.
            Pedido.objects.using(database).filter(pk=order.pk).update(status='CANCELADO')
        else:
            previous_user_id = order.usuario_id


